// Get current date
const now = new Date();

// Format helpers
const pad = (n) => n.toString().padStart(2, '0');

// TODAY
const today = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;

// YESTERDAY
const yd = new Date(now);
yd.setDate(now.getDate() - 1);
const yesterday = `${yd.getFullYear()}-${pad(yd.getMonth() + 1)}-${pad(yd.getDate())}`;

// TOMORROW
const tm = new Date(now);
tm.setDate(now.getDate() + 1);
const tomorrow = `${tm.getFullYear()}-${pad(tm.getMonth() + 1)}-${pad(tm.getDate())}`;

// LAST WEEK (7 jours en arrière)
const lw = new Date(now);
lw.setDate(now.getDate() - 7);
const lastWeek = `${lw.getFullYear()}-${pad(lw.getMonth() + 1)}-${pad(lw.getDate())}`;

// NEXT WEEK (7 jours en avant)
const nw = new Date(now);
nw.setDate(now.getDate() + 7);
const nextWeek = `${nw.getFullYear()}-${pad(nw.getMonth() + 1)}-${pad(nw.getDate())}`;

// CURRENT MONTH
const currentMonth = `${now.getFullYear()}-${pad(now.getMonth() + 1)}`;

// LAST MONTH
const lm = new Date(now);
lm.setMonth(now.getMonth() - 1);
const lastMonth = `${lm.getFullYear()}-${pad(lm.getMonth() + 1)}`;

// NEXT MONTH
const nm = new Date(now);
nm.setMonth(now.getMonth() + 1);
const nextMonth = `${nm.getFullYear()}-${pad(nm.getMonth() + 1)}`;

// CURRENT YEAR
const currentYear = `${now.getFullYear()}`;

// Return usable JSON
return [
  {
    today,
    yesterday,
    tomorrow,
    lastWeek,
    nextWeek,
    currentMonth,
    lastMonth,
    nextMonth,
    currentYear,
  }
];

